stereotypeDefinition.displayFunction:
const globs = (properties["Glob"].value || "")
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(line => line.length > 0)
    .join(", ");

const importance = (properties["Review Importance"].value || "").replace(/^\d+\s*-\s*/, "");

const classifications = JSON.parse(properties["Classification"].value || "[]")
    .map(id => lookup(id)?.getName())
    .filter(name => !!name)
    .join(", ");

const header = [importance, classifications].filter(part => !!part).join(" - ");

return `[${header}] ${globs}`.trim();
